export function serializeNodeError(error) {
    const value = typeof error === "object" && error !== null ? error : {};
    const errno = typeof value.errno === "number"
        ? { tag: "number", val: BigInt(value.errno) }
        : typeof value.errno === "string"
            ? { tag: "symbolic", val: value.errno }
            : undefined;
    return {
        name: typeof value.name === "string" ? value.name : "Error",
        message: typeof value.message === "string" ? value.message : String(error),
        code: typeof value.code === "string" ? value.code : undefined,
        errno,
        syscall: typeof value.syscall === "string" ? value.syscall : undefined,
        hostname: typeof value.hostname === "string" ? value.hostname : undefined,
        address: typeof value.address === "string" ? value.address : undefined,
        port: typeof value.port === "number" ? value.port : undefined,
    };
}
export function fieldsToRawHeaders(value) {
    const decoder = new TextDecoder("latin1");
    return value.flatMap(({ name, value: bytes }) => [name, decoder.decode(bytes)]);
}
export function rawHeadersToFields(rawHeaders) {
    const result = [];
    for (let index = 0; index < rawHeaders.length; index += 2) {
        result.push({
            name: rawHeaders[index],
            value: Uint8Array.from(rawHeaders[index + 1], (character) => character.charCodeAt(0)),
        });
    }
    return result;
}
